CREATE TABLE IF NOT EXISTS tracks (id TEXT PRIMARY KEY,title TEXT NOT NULL,mood TEXT NOT NULL,audio TEXT NOT NULL,cover TEXT NOT NULL,youtube TEXT,created BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'published',audience TEXT NOT NULL DEFAULT 'public',release_at BIGINT);
CREATE TABLE IF NOT EXISTS playlists (id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,track_ids TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY,track TEXT NOT NULL,country TEXT NOT NULL,at BIGINT NOT NULL,seconds INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS events_at_track ON events(at,track);
CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY,name TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1,expires BIGINT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY,pathname TEXT NOT NULL UNIQUE,content_type TEXT NOT NULL,size BIGINT NOT NULL,sha256 TEXT,created BIGINT NOT NULL);
